package com.phamquocviet.apigateway.filter;import org.springframework.cloud.gateway.filter.*;import org.springframework.core.Ordered;import org.springframework.http.*;import org.springframework.stereotype.Component;import org.springframework.web.server.*;import reactor.core.publisher.Mono;import java.nio.charset.StandardCharsets;
@Component public class AuthHeaderFilter implements GlobalFilter,Ordered{public Mono<Void> filter(ServerWebExchange x,GatewayFilterChain c){String p=x.getRequest().getPath().value();boolean publicCourseGet=x.getRequest().getMethod()==HttpMethod.GET&&p.matches("/api/courses(?:/[^/]+)?");if(p.equals("/api/auth/login")||p.startsWith("/api/public/courses")||publicCourseGet)return c.filter(x);String h=x.getRequest().getHeaders().getFirst(HttpHeaders.AUTHORIZATION);if(h==null||!h.startsWith("Bearer ")||h.length()==7)return error(x,"Thiếu hoặc sai định dạng Authorization Bearer");return c.filter(x);}private Mono<Void> error(ServerWebExchange x,String m){x.getResponse().setStatusCode(HttpStatus.UNAUTHORIZED);x.getResponse().getHeaders().setContentType(MediaType.APPLICATION_JSON);return x.getResponse().writeWith(Mono.just(x.getResponse().bufferFactory().wrap(("{\"status\":401,\"error\":\"Unauthorized\",\"message\":\""+m+"\"}").getBytes(StandardCharsets.UTF_8))));}public int getOrder(){return-10;}}
